/* 설계: original assets, source context and cut intent remain whole. */
@model original_model { version:0; length-unit:mm;
@curve #cut_source_unused { type:nurbs; degree:1; knots:[0.000,0,1,1.00]; control-points:[[-0,1,2],[3,4,2]]; weights:[1,2]; }
@surface #cut_surface { type:nurbs; degree-u:1; degree-v:1; knots-u:[0,0,4,4]; knots-v:[0,0,1,1]; control-points:[[[0,3,0],[0,3,8]],[[40,3,0],[40,3,8]]]; weights:[[1,1],[1,1]]; }
@surface #cut_source_sibling { type:nurbs; degree-u:1; degree-v:1; knots-u:[0,0,1,1]; knots-v:[0,0,1,1]; control-points:[[[2,3,-0],[2,5,1]],[[4,3,2],[4,5,4]]]; weights:[[1,2],[3,4]]; }
}
